        g_bTavernGameQuitRequested = false;
        state = (ETavernGameStates)47;
    }
    if (state == 5)
        GamePlayed = true;
    else if (state == 47) {
        LeaveGame();
        return;
    }
    PreviousTavernGameState = TavernGameState;
    TavernGameState = state;
