                game_master_member->GetPVillage();
            CPlayer& player = GetPlayerManager().GetMainPlayer();
            if (!CPlayerGui::Get().GetSubtitleRenderer().IsDisplayingText() && player.GetCurrentMode() != (EPlayerMode)26)
