            VillageHorns.push_back(&thing);
            break;
        }
        if ((bool)((object.GetProperties() >> 28) & 1)) {
            VillageGates.push_back(&thing);
            break;
        }
        if ((bool)((object.GetProperties() >> 3) & 1)) {
            VillageCages.push_back(&thing);
            break;
        }
        if ((bool)((object.GetProperties() >> 14) & 1)) {
