        weapon=hit.GetPWeapon();
        const C3DVector* position=hit.IsLocalised()?&hit.GetHitPosition():&physics.GetPosition();
        const C3DVector* direction=hit.IsDirectional()?&hit.GetHitDirection():&physics.GetRHSet().GetForward();
