                effect->SetFadeInTime(0);
                effect->SetFadeOutTime(0);
                effect->SetLifeTime(2);
            }
            CTCTalk* talk;
            if(GetTC(&talk)) {
                const CTCScriptedControl* script;
                if(talk->IsTalking() && (!PeekTC(&script) || !script->IsActive()))
