                haste->SetOnHitPause(combat.MeleeStrikeNumFramesPauseOnHeroStrike);
                if(!hitter->GetTC(&haste)) haste=static_cast<CTCHaste*>(hitter->AddTC("CTCHaste",false,0));
                haste->SetOnHitPause(combat.MeleeStrikeNumFramesPauseOnHeroStrike);
            }
