            else if(GetTC(&bullet))
                bullet->PlayCreatureOnHitEffect(this);
            const CTCCreatureModeManager* mode;
            if(PeekTC(&mode) && mode->GetCurrentMode().GetType()==NCreatureMode::MODE_DAZED && hit.IsKnockDown())
