                hit.SetPlayHitResponse(false);
                hit.SetDecapitate(false);
                hit.SetMoveBackOnHit(false);
            }
            if(GetHealth()<DELTA_NOTIONAL_ZERO) {
                hit.SetKnockDown(true);
                hit.SetPlayHitResponse(true);
            }
            ReactToGenericStrike(hit);
        }
    }
}

