    Morph m = {std::vector<const Tattoo*>(), false, 0};
    AddTattoo(m, &arm, 3); AddTattoo(m, &face, 4); AddTattoo(m, &face2, 5);
    if (m.worn.size() != 3 || !m.changed || m.frame != 5) { std::printf("0071d940_TEST FAIL\n"); return 1; }
