// none is valid.
#include <cstdio>
struct V { float X, Y, Z; };
static unsigned long Ror13(unsigned long v) { return (v >> 13) | (v << 19); }
static unsigned long GFRandom(unsigned long range, unsigned long* seed)
{
    *seed = *seed * 0x24a1 + 0x24df;
    *seed = Ror13(*seed);
    return range ? *seed % range : 0;
